    "ae_welfare_concern": "I don't want to add more, especially aimed at someone whose story I don't know.",
    "ce_understood_harm": "I don't want to add more, especially aimed at someone",
    "sys_consequence_reasoning": "There's already enough loss here, and I don't want to add more",
    "pda_practical_counterfactual": "Asking the organizer to pay on completion, with me present to show the finished job"
  },
  {
    "pda_practical_counterfactual": "the organizer ought to have had one rule from the beginning: payment goes to whoever signs off on the finished site."
  },
  {
    "sys_consequence_reasoning": "it's $100 from me, $300 from them, and zero to the person who did the work",
